import { s as serialize } from "../../../../../chunks/utils3.js";
const load = async () => {
  const comissoes = await db.comissao.findMany({
    include: {
      parceiro: true,
      empresa: true,
      payment: true
    },
    orderBy: {
      createdAt: "desc"
    }
  });
  return serialize({
    comissoes
  });
};
